#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sets up the signing of the plugin and the upload to the JetBrains Marketplace for the release workflow
# (.github/workflows/release.yml): a private key and a self-signed certificate, kept outside the repository, and the
# GitHub secrets and the variable the workflow reads. Run it in your own terminal from anywhere in the repository; it
# shows and asks for secrets, so it is not meant to run inside an AI session. Re-running it keeps an existing key.

# The secrets go into the protected environment the release workflow uses, not into the repository.
ENVIRONMENT=release

# set_env_secret NAME VALUE sets a secret of the environment, like set_secret does for the repository.
set_env_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" --env "$ENVIRONMENT" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s secret %s of the environment %s\n' "$GREEN" "$RESET" "$name" "$ENVIRONMENT"
      return
    fi
  fi
  SKIPPED+=("secret $name of the environment $ENVIRONMENT (set it by hand: gh secret set $name --env $ENVIRONMENT)")
  warn "skipped secret $name: gh is not ready, or the environment $ENVIRONMENT does not exist"
}

run_wizard() {

TOTAL_STAGES=10
cd "$(dirname "$0")/../.."
KEY_DIR_DEFAULT="$HOME/.aslan-signing"

banner "Signing and Marketplace upload for Aslan"

stage "A folder for the key"
say "The private key and the certificate are kept in a folder of their own, outside the repository."
say "The folder also gets signing.env with the answers below that are not secret; the password never goes to disk."
read -e -r -p "  Folder [$KEY_DIR_DEFAULT]: " KEY_DIR || true
KEY_DIR="${KEY_DIR:-$KEY_DIR_DEFAULT}"
KEY_DIR="${KEY_DIR/#\~/$HOME}"
[[ "$KEY_DIR" == /* ]] || KEY_DIR="$PWD/$KEY_DIR"
(umask 077 && mkdir -p "$KEY_DIR")
# Compare where the folders really are, after relative parts and symbolic links are resolved.
REPO_REAL=$(pwd -P)
KEY_DIR=$(cd "$KEY_DIR" && pwd -P)
case "$KEY_DIR" in
  "$REPO_REAL"|"$REPO_REAL"/*)
    rmdir "$KEY_DIR" 2>/dev/null || true
    warn "$KEY_DIR is inside the repository; choose a folder outside it."; exit 1;;
esac
chmod 700 "$KEY_DIR"
ENV_FILE="$KEY_DIR/signing.env"
KEY="$KEY_DIR/private_encrypted.pem"
CHAIN="$KEY_DIR/chain.crt"
say ""
say "The certificate names its owner. Use the name you want to stand behind the plugin,"
say "the same as the vendor name in plugin.xml and on the Marketplace."
ask CERT_NAME "Name in the certificate:"
write_env CERT_NAME "$CERT_NAME"
pause

stage "The password of the key"
if [[ -f "$KEY" ]]; then
  say "A key already exists in $KEY_DIR; it is kept. Enter its password."
  ask_secret PRIVATE_KEY_PASSWORD "Password of the existing key:"
  if ! PRIVATE_KEY_PASSWORD="$PRIVATE_KEY_PASSWORD" openssl pkey -in "$KEY" -passin env:PRIVATE_KEY_PASSWORD -noout 2>/dev/null; then
    warn "The password does not open the key."; exit 1
  fi
  say "The password opens the key."
else
  say "The key is stored encrypted with a password. The wizard makes a random one."
  PRIVATE_KEY_PASSWORD=$(openssl rand -base64 32)
  if command -v pbcopy >/dev/null 2>&1; then
    printf '%s' "$PRIVATE_KEY_PASSWORD" | pbcopy
    step "The password is on the clipboard. Save it in your password manager now, as 'Aslan plugin signing key'."
  else
    step "Save this password in your password manager now, as 'Aslan plugin signing key':"
    say "$PRIVATE_KEY_PASSWORD"
  fi
  pause "Saved it? Press Enter"
  command -v pbcopy >/dev/null 2>&1 && printf '' | pbcopy
fi
export PRIVATE_KEY_PASSWORD

stage "The private key"
if [[ -f "$KEY" ]]; then
  say "Kept the existing key: $KEY"
else
  say "Making an RSA key of 4096 bits, encrypted with the password."
  (umask 077 && openssl genpkey -aes-256-cbc -algorithm RSA -pkeyopt rsa_keygen_bits:4096 \
    -pass env:PRIVATE_KEY_PASSWORD -out "$KEY")
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$KEY"
fi
pause

stage "The certificate"
NEW_CHAIN=yes
if [[ -f "$CHAIN" ]]; then
  if [[ "$(openssl x509 -in "$CHAIN" -noout -pubkey)" != "$(openssl pkey -in "$KEY" -passin env:PRIVATE_KEY_PASSWORD -pubout)" ]]; then
    warn "The existing certificate belongs to another key than $KEY."
    say "If you still have the key that belongs to it, stop now (Ctrl-C), put that key in $KEY_DIR and run the wizard again."
    confirm "Make a new certificate for the key in $KEY_DIR instead?" || exit 1
  elif ! confirm "A certificate for this key exists ($(openssl x509 -in "$CHAIN" -noout -enddate)). Make a new one?"; then
    NEW_CHAIN=no
  fi
fi
if [[ "$NEW_CHAIN" == no ]]; then
  say "Kept the existing certificate."
else
  say "Making a self-signed certificate for '$CERT_NAME', valid for ten years."
  openssl req -new -x509 -sha256 -days 3650 -key "$KEY" -passin env:PRIVATE_KEY_PASSWORD \
    -subj "/CN=$CERT_NAME" -out "$CHAIN"
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$CHAIN"
fi
openssl x509 -in "$CHAIN" -noout -subject -enddate -fingerprint -sha256 | sed 's/^/  /'
pause

stage "A backup"
say "Without the key and its password, later versions cannot be signed with the same certificate."
step "Attach $KEY and $CHAIN to the password manager entry, or copy them to another safe place."
note "The key file is encrypted, so it is useless without the password."
pause "Backed up? Press Enter"

stage "A test of the signing"
say "Builds the plugin and signs it with the new key, as the release workflow will."
if confirm "Run ./gradlew buildPlugin signPlugin verifyPluginSignature now?"; then
  CERTIFICATE_CHAIN="$(cat "$CHAIN")" PRIVATE_KEY="$(cat "$KEY")" \
    ./gradlew buildPlugin signPlugin verifyPluginSignature -Pversion=1.0.0-signing-test --quiet
  ls build/distributions/*-signing-test-signed.zip >/dev/null
  printf '  %s✓ signed and verified%s\n' "$GREEN" "$RESET"
  rm -f build/distributions/*-signing-test*.zip
else
  note "Skipped."
fi
pause

stage "GitHub secrets for signing"
say "The release workflow signs with CERTIFICATE_CHAIN, PRIVATE_KEY and PRIVATE_KEY_PASSWORD."
say "They are stored in the environment $ENVIRONMENT, which hands them only to approved runs from v* tags."
say "Repository: $(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || echo 'unknown, gh is not ready')"
if confirm "Set the three secrets now (an existing one is replaced)?"; then
  set_env_secret CERTIFICATE_CHAIN "$(cat "$CHAIN")"
  set_env_secret PRIVATE_KEY "$(cat "$KEY")"
  set_env_secret PRIVATE_KEY_PASSWORD "$PRIVATE_KEY_PASSWORD"
else
  SKIPPED+=("the GitHub secrets for signing (re-run this wizard)")
fi
pause

stage "Marketplace token"
say "For uploads by the release workflow, a token of your JetBrains Marketplace account."
say "You can do this now or later; it needs your account on plugins.jetbrains.com."
if confirm "Create and store the token now?"; then
  open_url "https://plugins.jetbrains.com/author/me/tokens"
  step "Sign in, choose to generate a new token, and name it 'aslan release workflow'."
  step "Copy the token; the page shows it only once."
  ask_secret MARKETPLACE_TOKEN "Paste the token:"
  set_env_secret MARKETPLACE_TOKEN "$MARKETPLACE_TOKEN"
else
  SKIPPED+=("the secret MARKETPLACE_TOKEN (re-run this wizard)")
fi
pause

stage "Uploads by the release workflow"
say "The first version must be uploaded by hand on plugins.jetbrains.com (see docs/marketplace/listing.md)."
say "Once JetBrains has approved it, the release workflow can upload each new version itself."
if confirm "Has the first version been approved, and should releases now be uploaded automatically?"; then
  set_var MARKETPLACE_UPLOAD true
else
  SKIPPED+=("the variable MARKETPLACE_UPLOAD=true, after the first version is approved (re-run this wizard)")
fi
pause

stage "Old repository secrets"
say "Earlier versions of this wizard stored the secrets in the repository, where any workflow can read them."
say "Copies that the environment $ENVIRONMENT now holds as well can be deleted from the repository."
OLD_SECRETS=()
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  REPO_SECRETS=$(gh secret list --json name -q '.[].name' 2>/dev/null || true)
  ENV_SECRETS=$(gh secret list --env "$ENVIRONMENT" --json name -q '.[].name' 2>/dev/null || true)
  for name in CERTIFICATE_CHAIN PRIVATE_KEY PRIVATE_KEY_PASSWORD MARKETPLACE_TOKEN; do
    if grep -qx "$name" <<< "$REPO_SECRETS" && grep -qx "$name" <<< "$ENV_SECRETS"; then
      OLD_SECRETS+=("$name")
    fi
  done
fi
if (( ${#OLD_SECRETS[@]} == 0 )); then
  note "None found."
elif confirm "Delete the repository secrets ${OLD_SECRETS[*]}?"; then
  for name in "${OLD_SECRETS[@]}"; do
    if gh secret delete "$name" >/dev/null 2>&1; then
      printf '  %s✓ deleted%s repository secret %s\n' "$GREEN" "$RESET" "$name"
    else
      warn "could not delete the repository secret $name; delete it under Settings | Secrets and variables | Actions"
    fi
  done
else
  SKIPPED+=("deleting the repository secrets ${OLD_SECRETS[*]} (re-run this wizard)")
fi
pause

finish
}

run_wizard "$@"; exit
